public class Main {
    // Subnet calculator with bit operations. O(1) time and space.
    static String dotted(long n) {
        return ((n >> 24) & 255) + "." + ((n >> 16) & 255) + "." + ((n >> 8) & 255) + "." + (n & 255);
    }

    public static void main(String[] args) {
        long ip = (192L << 24) | (168L << 16) | (10L << 8) | 77;
        int prefix = 26;
        long all = 0xFFFFFFFFL;
        long mask = (all << (32 - prefix)) & all;   // prefix ones, then zeros
        long network = ip & mask;                   // AND keeps the network bits
        long broadcast = network | (~mask & all);   // host bits all ones
        long hosts = (1L << (32 - prefix)) - 2;     // minus network and broadcast

        System.out.println("Address: " + dotted(ip) + "/" + prefix);
        System.out.println("Mask: " + dotted(mask));
        System.out.println("Network: " + dotted(network));
        System.out.println("Broadcast: " + dotted(broadcast));
        System.out.println("First host: " + dotted(network + 1));
        System.out.println("Last host: " + dotted(broadcast - 1));
        System.out.println("Usable hosts: " + hosts);
    }
}

