// Subnet calculator with bit operations. O(1) time and space.
const ip = ((192 << 24) | (168 << 16) | (10 << 8) | 77) >>> 0;
const prefix = 26;

function dotted(n) {
  return [24, 16, 8, 0].map(s => (n >>> s) & 255).join(".");
}

const mask = (0xFFFFFFFF << (32 - prefix)) >>> 0;  // prefix ones, then zeros
const network = (ip & mask) >>> 0;                 // AND keeps the network bits
const broadcast = (network | ~mask) >>> 0;         // host bits all ones
const hosts = 2 ** (32 - prefix) - 2;              // minus network and broadcast

console.log("Address: " + dotted(ip) + "/" + prefix);
console.log("Mask: " + dotted(mask));
console.log("Network: " + dotted(network));
console.log("Broadcast: " + dotted(broadcast));
console.log("First host: " + dotted(network + 1));
console.log("Last host: " + dotted(broadcast - 1));
console.log("Usable hosts: " + hosts);

