# IPv6 shorten and expand by hand. O(1): at most 8 groups.
def shorten(addr):
    groups = [g.lstrip("0") or "0" for g in addr.split(":")]  # drop leading zeros
    best_start, best_len, i = -1, 0, 0
    while i < 8:                                  # find the longest run of zeros
        if groups[i] == "0":
            j = i
            while j < 8 and groups[j] == "0":
                j += 1
            if j - i > best_len:
                best_start, best_len = i, j - i
            i = j
        else:
            i += 1
    if best_len < 2:                              # a single zero group is not replaced
        return ":".join(groups)
    return ":".join(groups[:best_start]) + "::" + ":".join(groups[best_start + best_len:])

def expand(addr):
    if "::" in addr:
        left, right = addr.split("::")
        l = left.split(":") if left else []
        r = right.split(":") if right else []
        groups = l + ["0"] * (8 - len(l) - len(r)) + r   # fill the gap with zeros
    else:
        groups = addr.split(":")
    return ":".join(g.zfill(4) for g in groups)

full = "2001:0db8:0000:0000:0000:ff00:0042:8329"
short = shorten(full)
print("full    :", full)
print("short   :", short)
print("expanded:", expand(short))
print("loopback:", shorten("0000:0000:0000:0000:0000:0000:0000:0001"))
print("expanded:", expand("fe80::1"))
